using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using POS.API.Authorization;using POS.Application.RestaurantInventory;using POS.Domain.Constants;namespace POS.API.Controllers;[ApiController,Route("api/stock-counts"),Authorize,RequirePermission(PermissionKeys.InventoryAdjust)]public class StockCountsController(StockCountService s):ControllerBase{[HttpPost]public async Task<IActionResult>Start(StartInput r,CancellationToken ct)=>Ok(await s.Start(r.BranchId,r.WarehouseId,ct));[HttpGet("{id:guid}")]public async Task<IActionResult>Get(Guid id,CancellationToken ct)=>Ok(await s.Get(id,ct));[HttpPut("{id:guid}")]public async Task<IActionResult>Save(Guid id,List<CountLineInput> r,CancellationToken ct){await s.Save(id,r,ct);return NoContent();}[HttpPost("{id:guid}/finalize")]public async Task<IActionResult>Finalize(Guid id,CancellationToken ct){await s.Finalize(id,ct);return NoContent();}public record StartInput(Guid BranchId,Guid WarehouseId);}
